<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamReportMemberDTO; use Inc\Enums\Settings\TableName; class ExamReportMemberRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamReportMembers->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamReportMemberDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamReportMemberDTO::fromArray( $row ) : null; } public function findByReport( int $reportId ): array { $rows = $this->wpdb->get_results( $this->wpdb->prepare( "SELECT * FROM %i WHERE report_id = %d", $this->table, $reportId ), ARRAY_A ); return array_map( [ ExamReportMemberDTO::class, 'fromArray' ], $rows ?: [] ); } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
